def abonos_existentes_al_libro(apps, schema_editor):
    """Cada hito con dinero ya abonado recibe una fila con ese monto (método «Otro»), para que el libro sume lo mismo que el hito."""
    Hito, Registro = apps.get_model('core', 'HitoPago'), apps.get_model('core', 'DetalleRegistro')
    for h in Hito.objects.filter(monto_abonado__gt=0):
        Registro.objects.create(hito=h, monto=h.monto_abonado, metodo='OTRO', fecha=h.fecha_pago or h.cotizacion.fecha_creacion.date(),
                                nota='Pago registrado antes del libro de pagos')


